class ai_goal {
protected:
  void *owner;
  rational_t priority;
  rational_t priority_modifier;

  virtual rational_t frame_advance(time_value_t t);
  virtual void unused0();
  virtual void unused1();
  virtual void unused2();
  virtual void unused3();
  virtual void unused4();
  virtual void unused5();
  virtual void unused6();
  virtual void unused7();
  virtual void unused8();
  virtual void unused9();
  virtual void unused10();
  virtual void unused11();
  virtual void unused12();
  virtual void going_into_service();
  virtual void going_out_of_service();

public:
  rational_t get_priority() { return priority * priority_modifier; }

  static int compare(const void *x1, const void *x2)
  {
    rational_t diff = (*((ai_goal **)x1))->get_priority() - (*((ai_goal **)x2))->get_priority();
    if (diff < 0.0f)
      return 1;
    if (diff > 0.0f)
      return -1;
    return 0;
  }

  friend class ai_interface;
};

template<class T> class vector {
  T *start;
  T *finish;
  T *end_of_storage;
public:
  bool empty() const { return start == finish; }
  size_t size() const { return finish - start; }
  T *begin() { return start; }
};

class ai_interface {
  void *vtable;
  void *my_entity;
  unsigned int flags;
  unsigned int team;
  unsigned int enemy_team;
  ai_locomotion *locomotion;
  vector<ai_goal *> goals;
  ai_goal *current_goal;

  void set_reached_dest(bool a)
  {
    if (a)
      flags |= 0x40;
    else
      flags &= ~0x40;
  }

public:
  virtual void frame_advance(time_value_t t);
};

#define START_PROF_TIMER(x)
#define STOP_PROF_TIMER(x)

void ai_interface::frame_advance(time_value_t t)
{
  START_PROF_TIMER(proftimer_adv_AI_locomotion);
  set_reached_dest(locomotion == 0 ? true : locomotion->frame_advance(t));
  STOP_PROF_TIMER(proftimer_adv_AI_locomotion);

  START_PROF_TIMER(proftimer_adv_AI_priority);
  if(!goals.empty())
  {
    if(goals.size() > 1)
      qsort( &(*goals.begin()), goals.size(), sizeof(ai_goal *), ai_goal::compare );

    ai_goal *goal = *goals.begin();

    if(!current_goal || (goal->get_priority() > 0.0f && (current_goal != *goals.begin() && (!current_goal || goal->get_priority() > current_goal->get_priority()))))
    {
      if(current_goal)
        current_goal->going_out_of_service();

      current_goal = *goals.begin();
      current_goal->going_into_service();
    }
  }
  STOP_PROF_TIMER(proftimer_adv_AI_priority);

  START_PROF_TIMER(proftimer_adv_AI_goal);
  if(current_goal)
    current_goal->frame_advance(t);
  STOP_PROF_TIMER(proftimer_adv_AI_goal);
}
